// Shared helpers. Pure functions, no imports, so they can be inlined into n8n Code nodes.

function sha256(message) {
  // Compact pure-JS SHA-256 (UTF-8). Used to lock DTP versions and detect duplicate documents
  // without requiring Node built-in modules inside the n8n sandbox.
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const bytes = Array.from(unescape(encodeURIComponent(String(message))), (c) => c.charCodeAt(0));
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < bytes.length; i += 64) {
    const w = new Array(64);
    for (let t = 0; t < 16; t++) {
      w[t] = (bytes[i + 4 * t] << 24) | (bytes[i + 4 * t + 1] << 16) | (bytes[i + 4 * t + 2] << 8) | bytes[i + 4 * t + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

function nowIso() {
  return new Date().toISOString();
}

function addDays(iso, days) {
  const d = new Date(iso);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString();
}

function round(n, decimals = 2) {
  const f = 10 ** decimals;
  return Math.round(Number(n) * f) / f;
}

function parseMoney(text) {
  if (text === null || text === undefined) return null;
  const m = String(text).replace(/,/g, '').match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]) : null;
}

function fmtMoney(n, currency = 'BZD') {
  if (n === null || n === undefined || Number.isNaN(Number(n))) return '—';
  return `${currency} ${Number(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
}

function auditEvent(actor, role, action, detail = {}) {
  return { at: nowIso(), actor, role, action, detail };
}

function makeFlag(code, severity, message, evidence = null) {
  // severity: "info" | "warning" | "blocking" (blocking = needs a human decision before the case can advance)
  return { code, severity, message, evidence, status: 'open' };
}

function slaWindow(stepKey, rulebook, startIso = nowIso()) {
  const days = (rulebook.sla_days || {})[stepKey];
  return { step: stepKey, started_at: startIso, due_at: days ? addDays(startIso, days) : null, sla_days: days || null };
}


// STEP 1 (pre-screening) — normalizes the BELTRAIDE "MSME Digital Transformation and Export Readiness
// Expression of Interest 2027" form and applies deterministic intake rules.
// The tier thresholds are the official ones printed on the form (see rulebook.tiers).

const EOI_FIELDS = {
  email: 'Email',
  applicantName: 'Applicant Name',
  businessName: 'Business Name',
  contactNumber: 'Contact Number',
  gender: 'Gender',
  age: 'Age',
  address: 'Address (Street/City/Town/Village/District)',
  sector: 'Which sector of the economy does your business belong to?',
  businessDescription: 'Describe your business venture (product/service line, customers)',
  registered: 'Is your business registered?',
  category: 'Which category best describes your business?',
  supportInterest: 'What support is your business interested in receiving?',
  digitalTools: 'Which digital tools does your business currently use?',
  exportExperience: "Which statement best describes your business's export experience?",
  socialLinks: 'Please include social media link(s) for your business',
  improvementGoals: 'Briefly describe what you would like to improve in your business',
  acknowledgment: 'I understand this form records interest only (not an official grant application)',
  contactPermission: 'May BELTRAIDE contact you about relevant opportunities?',
  freeAdvising: 'Would you like to receive additional free business advising through BELTRAIDE?',
};

const REQUIRED_EOI_KEYS = [
  'email', 'applicantName', 'businessName', 'contactNumber', 'address', 'sector',
  'businessDescription', 'registered', 'category', 'supportInterest', 'digitalTools',
  'exportExperience', 'improvementGoals', 'acknowledgment',
];

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v === undefined || v === null || v === '') return [];
  return String(v).split(',').map((s) => s.trim()).filter(Boolean);
}

function normalizeEoi(form) {
  const get = (key) => form[EOI_FIELDS[key]];
  const eoi = {};
  const multi = ['digitalTools', 'acknowledgment'];
  for (const key of Object.keys(EOI_FIELDS)) {
    const v = get(key) ?? null;
    eoi[key] = !multi.includes(key) && Array.isArray(v) ? (v[0] ?? null) : v;
  }
  eoi.digitalTools = asArray(eoi.digitalTools);
  eoi.acknowledgment = asArray(eoi.acknowledgment).length > 0 || eoi.acknowledgment === true;
  // Category arrives as the long label; keep a short code too.
  const cat = String(eoi.category || '').toLowerCase();
  eoi.categoryCode = cat.startsWith('micro') ? 'micro' : cat.startsWith('small') ? 'small'
    : cat.startsWith('medium') ? 'medium' : cat.startsWith('unsure') ? 'unsure' : null;
  return eoi;
}

function detectDistrict(address, districts) {
  const a = String(address || '').toLowerCase();
  // Longest names first so "Belize" (district) does not shadow "Orange Walk" etc.
  const sorted = [...districts].sort((x, y) => y.length - x.length);
  return sorted.find((d) => a.includes(d.toLowerCase())) || null;
}

function classifyTier(numbers, rulebook) {
  // numbers: { employees, annual_sales, capital_investment, space_m2 }
  // Returns the tier implied by EACH criterion, the proposed tier and whether criteria diverge.
  const { order } = rulebook.tiers;
  const criteria = [
    ['employees', 'employees_below'],
    ['annual_sales', 'annual_sales_below'],
    ['capital_investment', 'capital_below'],
    ['space_m2', 'space_m2_below'],
  ];
  const perCriterion = {};
  for (const [field, limitKey] of criteria) {
    const v = numbers[field];
    if (v === null || v === undefined || v === '') continue;
    let found = null;
    for (const tier of order) {
      const limit = rulebook.tiers[tier][limitKey];
      if (limit === null || limit === undefined) continue; // e.g. micro has no space limit
      if (Number(v) < limit) { found = tier; break; }
    }
    perCriterion[field] = found || 'above_medium';
  }
  const values = Object.values(perCriterion);
  if (values.length === 0) return { per_criterion: {}, proposed: null, diverges: false, exceeds_medium: false };
  const exceeds = values.includes('above_medium');
  const counts = {};
  values.forEach((t) => { counts[t] = (counts[t] || 0) + 1; });
  // Majority; ties resolved to the larger tier (staff confirms — never automatic).
  const rank = (t) => (t === 'above_medium' ? 99 : order.indexOf(t));
  const proposed = Object.keys(counts).sort((a, b) => counts[b] - counts[a] || rank(b) - rank(a))[0];
  return { per_criterion: perCriterion, proposed, diverges: new Set(values).size > 1, exceeds_medium: exceeds };
}

function runIntake(eoi, rulebook) {
  const flags = [];
  const checks = [];
  const missing = REQUIRED_EOI_KEYS.filter((k) => eoi[k] === null || eoi[k] === '' ||
    (Array.isArray(eoi[k]) && eoi[k].length === 0) || eoi[k] === false);
  checks.push({ id: 'R1.01', rule: 'All required EOI fields answered', result: missing.length ? 'fail' : 'pass', detail: missing });
  if (missing.length) flags.push({ code: 'EOI_INCOMPLETE', severity: 'blocking', message: `Missing: ${missing.join(', ')}`, status: 'open' });

  const district = detectDistrict(eoi.address, rulebook.program.belize_districts);
  checks.push({ id: 'R1.02', rule: 'Address located in a Belize district', result: district ? 'pass' : 'needs_review', detail: district });
  if (!district) flags.push({ code: 'LOCATION_UNVERIFIED', severity: 'warning', message: 'No Belize district found in the address', status: 'open' });

  const sectorOk = rulebook.program.eligible_sectors.includes(eoi.sector);
  checks.push({ id: 'R1.03', rule: 'Sector is one of the program sectors', result: sectorOk ? 'pass' : 'needs_review', detail: eoi.sector });
  if (!sectorOk) flags.push({ code: 'SECTOR_NOT_LISTED', severity: 'warning', message: `Sector "${eoi.sector}" not in the list`, status: 'open' });

  const registered = String(eoi.registered).toLowerCase() === 'yes';
  checks.push({ id: 'R1.04', rule: 'Business declares it is registered', result: registered ? 'pass' : 'needs_review', detail: eoi.registered });
  if (!registered) flags.push({ code: 'NOT_REGISTERED', severity: 'blocking', message: 'Business declares it is not registered: staff to advise on registration before applying', status: 'open' });

  const tools = eoi.digitalTools.filter((t) => t !== 'None currently');
  checks.push({ id: 'R1.05', rule: 'Digital maturity indicator (number of digital tools)', result: 'info', detail: tools.length });

  if (eoi.categoryCode === 'unsure') {
    flags.push({ code: 'CATEGORY_UNSURE', severity: 'info', message: 'Applicant needs help determining the category; tier will be computed from DTP figures', status: 'open' });
  }
  if (eoi.categoryCode === 'medium' && tools.length < rulebook.tiers.medium.min_digital_tools_for_maturity) {
    flags.push({ code: 'MATURITY_CHECK', severity: 'warning', message: `Medium tier requires advanced digital maturity; only ${tools.length} digital tool(s) declared`, status: 'open' });
  }

  // Time constraint: will a case that starts today finish before the program ends?
  const projectedEnd = new Date(Date.now() + rulebook.program.expected_cycle_days * 86400000);
  const programEnd = new Date(rulebook.program.end_date);
  const fitsWindow = projectedEnd <= programEnd;
  checks.push({ id: 'R1.06', rule: 'Expected 5–6 month cycle fits before program end', result: fitsWindow ? 'pass' : 'needs_review',
    detail: { projected_close: projectedEnd.toISOString().slice(0, 10), program_end: rulebook.program.end_date } });
  if (!fitsWindow) flags.push({ code: 'PROGRAM_WINDOW_RISK', severity: 'warning', message: 'Case may not close before the program end date', status: 'open' });

  const grantCap = eoi.categoryCode && rulebook.tiers[eoi.categoryCode] ? rulebook.tiers[eoi.categoryCode].grant_cap : null;
  return {
    district, digital_tools_count: tools.length, declared_tier: eoi.categoryCode, indicative_grant_cap: grantCap,
    checks, flags,
    outcome: flags.some((f) => f.severity === 'blocking') ? 'NEEDS_STAFF_FOLLOW_UP' : 'INVITE_TO_FORMAL_APPLICATION',
  };
}


// Bounded AI extraction. The model ONLY extracts values and the exact quote/page they come from.
// It never decides eligibility, scores, matches or acceptances: those are rules + humans.
// Every quote returned by the model is verified against the source text (anti-hallucination guard).

const DTP_SCHEMA_HINT = {
  business_name: 'field', registration_number: 'field', district: 'field',
  employees: 'field(number)', annual_sales: 'field(number, BZD)', capital_investment: 'field(number, BZD)',
  manufacturing_space_m2: 'field(number|null)', amount_requested: 'field(number, BZD)',
  budget_total_declared: 'field(number, BZD)', responsible_person: 'field',
  problem_statement: 'field', solution_summary: 'field',
  timeline_start: 'field(YYYY-MM-DD)', timeline_end: 'field(YYYY-MM-DD)',
  objectives: '[{ text, metric, target, date(YYYY-MM-DD|null), quote, page }]',
  budget_lines: '[{ category, description, amount(number), quote, page }]',
  services_required: '[category]',
  suggested_scores: '{ C1: { points, rationale, quote, page }, C2: { points, rationale, quote, page } }',
};

const REPORT_SCHEMA_HINT = {
  report_date: 'field(YYYY-MM-DD)',
  payment_payer: 'field', payment_payee: 'field', payment_amount: 'field(number, BZD)',
  payment_date: 'field(YYYY-MM-DD)', payment_reference: 'field',
  invoice_issuer: 'field', invoice_number: 'field', invoice_date: 'field(YYYY-MM-DD)', invoice_amount: 'field(number, BZD)',
  contract_provider: 'field', contract_value: 'field(number, BZD)', contract_signed: 'field(YYYY-MM-DD)',
  milestones: '[{ objective_id, status(completed|in_progress|not_started), evidence, quote, page }]',
};

function docsToText(documents) {
  return documents.map((d) => `=== DOCUMENT: ${d.type} | ${d.name} ===\n${d.text}`).join('\n\n');
}

function buildExtractionRequest(kind, documents, rulebook, extra = {}) {
  const schema = kind === 'dtp' ? DTP_SCHEMA_HINT : REPORT_SCHEMA_HINT;
  const categories = rulebook.dtp_review.service_categories.join(', ');
  const criteria = rulebook.screening.criteria.filter((c) => c.method !== 'deterministic')
    .map((c) => `${c.id} "${c.name}" (0-${c.max})`).join('; ');
  const system = [
    'You are a document extraction component inside a public grant program workflow (BELTRAIDE DIBED, Belize).',
    'Your ONLY job is to extract values from the documents provided. You do not decide eligibility, scores, matches or approvals.',
    'Rules:',
    '1. Return ONLY valid JSON, no prose, no markdown fences.',
    '2. A "field" is an object: {"value": ..., "quote": "<exact text copied from the document>", "page": <page number from the [Page N] marker>, "confidence": <0..1>}.',
    '3. "quote" must be copied verbatim from the document (max 25 words). If a value is not in the documents, return {"value": null, "quote": null, "page": null, "confidence": 0}. Never guess.',
    `4. Budget and service categories must be one of: ${categories}. Use "uncategorized" if none fits.`,
    kind === 'dtp' ? `5. suggested_scores: suggest points ONLY for ${criteria}, each with a one-sentence rationale and a supporting quote. These are suggestions for a human panel, not decisions.` : '5. milestones: objective_id refers to the DTP objective ids (O1, O2, ...).',
    '6. Amounts are numbers in BZD without separators.',
  ].join('\n');
  const user = [
    `Extract this JSON structure:\n${JSON.stringify(schema, null, 2)}`,
    extra.context ? `Context:\n${extra.context}` : '',
    `Documents:\n${docsToText(documents)}`,
  ].filter(Boolean).join('\n\n');
  return {
    model: (extra.model || rulebook.ai.model),
    max_tokens: rulebook.ai.max_tokens,
    temperature: rulebook.ai.temperature,
    system,
    messages: [{ role: 'user', content: user }],
  };
}

function parseModelJson(apiResponse) {
  const text = (apiResponse && apiResponse.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  const cleaned = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end < 0) throw new Error('Model did not return JSON');
  return JSON.parse(cleaned.slice(start, end + 1));
}

function normalizeSpace(s) {
  return String(s || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();
}

function verifyCitations(extraction, documents, minConfidence = 0.8) {
  // Walks every {value, quote} pair and checks the quote exists in the source documents.
  const corpus = normalizeSpace(documents.map((d) => d.text).join('\n'));
  const issues = [];
  let checked = 0;
  let verified = 0;
  const visit = (node, path) => {
    if (Array.isArray(node)) { node.forEach((n, i) => visit(n, `${path}[${i}]`)); return; }
    if (!node || typeof node !== 'object') return;
    if ('quote' in node && node.quote) {
      checked += 1;
      const q = normalizeSpace(node.quote).replace(/\.\.\.|…/g, '');
      const ok = q.length > 0 && corpus.includes(q.slice(0, Math.min(q.length, 120)));
      if (ok) verified += 1;
      else {
        node.confidence = Math.min(Number(node.confidence ?? 1), 0.3);
        node.citation_verified = false;
        issues.push({ path, quote: node.quote, problem: 'CITATION_NOT_FOUND' });
      }
      if (ok) node.citation_verified = true;
    }
    if ('confidence' in node && 'value' in node && node.value !== null && Number(node.confidence) < minConfidence &&
        !issues.find((i) => i.path === path)) {
      issues.push({ path, value: node.value, problem: 'LOW_CONFIDENCE', confidence: node.confidence });
    }
    for (const [k, v] of Object.entries(node)) if (v && typeof v === 'object') visit(v, path ? `${path}.${k}` : k);
  };
  visit(extraction, '');
  return { checked, verified, issues };
}

function val(field) {
  // Reads the value of a {value, quote, ...} field, tolerating plain values.
  if (field && typeof field === 'object' && 'value' in field) return field.value;
  return field ?? null;
}

function estimateCostUsd(usage, rulebook) {
  if (!usage) return 0;
  const p = rulebook.ai.cost_assumptions_usd_per_million_tokens;
  return ((usage.input_tokens || 0) * p.input + (usage.output_tokens || 0) * p.output) / 1e6;
}


// STEP 2 — Screening & evaluation. Deterministic rules over the AI-extracted (and citation-verified) data.
// Output is a PRELIMINARY result for the panel. It never rejects and never sets a final score.
// Depends on: classifyTier (intake.js), val (extraction.js)

function runScreening({ eoi, documents, extraction, citationCheck, rulebook }) {
  const S = rulebook.screening;
  const checks = [];
  const flags = [];
  const flag = (code, severity, message, evidence = null) => flags.push({ code, severity, message, evidence, status: 'open' });
  const check = (id, rule, result, detail = null) => checks.push({ id, rule, result, detail });

  // R2.01 completeness of mandatory documents
  const present = new Set(documents.map((d) => d.type));
  const missingDocs = S.mandatory_documents.filter((t) => !present.has(t));
  check('R2.01', 'All mandatory documents present', missingDocs.length ? 'fail' : 'pass', missingDocs);
  if (missingDocs.length) flag('MISSING_DOC', 'blocking', `Missing mandatory document(s): ${missingDocs.join(', ')} — request from MSME, do not reject`);

  // R2.02 registration
  const reg = val(extraction.registration_number);
  const registered = String(eoi.registered).toLowerCase() === 'yes' && !!reg;
  check('R2.02', 'Registered business (EOI = Yes and registration number found)', registered ? 'pass' : 'fail', reg);
  if (!registered) flag('REGISTRATION_UNVERIFIED', 'blocking', 'No registration number found in the documents');

  // R2.03 tier from extracted figures vs. self-declared EOI category
  const tier = classifyTier({
    employees: val(extraction.employees), annual_sales: val(extraction.annual_sales),
    capital_investment: val(extraction.capital_investment), space_m2: val(extraction.manufacturing_space_m2),
  }, rulebook);
  check('R2.03', 'Tier computed from DTP figures (official EOI thresholds)', tier.proposed ? 'pass' : 'needs_review', tier);
  if (tier.exceeds_medium) flag('SIZE_ABOVE_MEDIUM', 'blocking', 'At least one size criterion is above the medium-enterprise threshold', tier.per_criterion);
  if (tier.diverges) flag('TIER_CRITERIA_DIVERGE', 'warning', `Size criteria point to different tiers: ${JSON.stringify(tier.per_criterion)}`);
  if (eoi.categoryCode && eoi.categoryCode !== 'unsure' && tier.proposed && eoi.categoryCode !== tier.proposed) {
    flag('CONFLICT_DECLARED_TIER', 'warning', `EOI declared "${eoi.categoryCode}" but DTP figures indicate "${tier.proposed}"`);
  }
  const tierKey = tier.proposed && rulebook.tiers[tier.proposed] ? tier.proposed : eoi.categoryCode;
  const grantCap = tierKey && rulebook.tiers[tierKey] ? rulebook.tiers[tierKey].grant_cap : null;

  // R2.04 medium tier needs advanced digital maturity
  if (tierKey === 'medium') {
    const tools = (eoi.digitalTools || []).filter((t) => t !== 'None currently').length;
    const ok = tools >= rulebook.tiers.medium.min_digital_tools_for_maturity;
    check('R2.04', 'Medium tier: advanced digital maturity indicator', ok ? 'pass' : 'needs_review', { digital_tools: tools });
    if (!ok) flag('MATURITY_INSUFFICIENT', 'warning', 'Medium tier requires advanced digital maturity');
  }

  // R2.05 amount requested within cap
  const requested = val(extraction.amount_requested);
  const withinCap = requested !== null && grantCap !== null && requested <= grantCap;
  check('R2.05', 'Amount requested ≤ tier grant cap', withinCap ? 'pass' : 'fail', { requested, grantCap, tier: tierKey });
  if (!withinCap) flag('ABOVE_GRANT_CAP', 'blocking', `Requested ${requested} exceeds cap ${grantCap} for tier ${tierKey}`);

  // R2.06 budget arithmetic
  const lines = extraction.budget_lines || [];
  const sum = lines.reduce((a, b) => a + (Number(b.amount) || 0), 0);
  const declared = val(extraction.budget_total_declared);
  const sumOk = declared !== null && Math.abs(sum - declared) <= declared * S.budget_sum_tolerance;
  check('R2.06', 'Sum of budget lines = declared total (±1%)', sumOk ? 'pass' : 'fail', { sum, declared });
  if (!sumOk) flag('BUDGET_SUM_MISMATCH', 'warning', `Budget lines add up to ${sum}, declared total is ${declared}`);
  const uncategorized = lines.filter((l) => !rulebook.dtp_review.service_categories.includes(l.category));
  if (uncategorized.length) flag('UNCATEGORIZED_BUDGET_LINE', 'warning', `${uncategorized.length} budget line(s) without a valid service category`);

  // R2.07 identity consistency EOI vs DTP
  const nameDtp = String(val(extraction.business_name) || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const nameEoi = String(eoi.businessName || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const nameOk = nameDtp && nameEoi && (nameDtp.includes(nameEoi) || nameEoi.includes(nameDtp));
  check('R2.07', 'Business name in EOI matches DTP', nameOk ? 'pass' : 'needs_review', { eoi: eoi.businessName, dtp: val(extraction.business_name) });
  if (!nameOk) flag('CONFLICT_BUSINESS_NAME', 'warning', 'Business name differs between EOI and DTP');

  // Citation / confidence guard from the AI layer
  for (const issue of (citationCheck && citationCheck.issues) || []) {
    flag(issue.problem === 'CITATION_NOT_FOUND' ? 'CITATION_NOT_FOUND' : 'LOW_CONFIDENCE', 'warning',
      `${issue.path}: ${issue.problem}`, issue.quote || issue.value);
  }

  // ---- Preliminary score /80 ----
  const crit = Object.fromEntries(S.criteria.map((c) => [c.id, c]));
  const scores = [];
  const ai = extraction.suggested_scores || {};
  for (const id of ['C1', 'C2']) {
    const sug = ai[id] || {};
    const pts = Math.max(0, Math.min(crit[id].max, Number(sug.points) || 0));
    scores.push({ id, name: crit[id].name, max: crit[id].max, points: pts, method: extraction._extractor === 'deterministic_fallback' ? 'heuristic_fallback' : 'ai_suggested',
      needs_human_confirmation: true, rationale: sug.rationale || null, quote: sug.quote || null, page: sug.page || null });
  }
  const objectives = extraction.objectives || [];
  const validObjectives = objectives.filter((o) => o.metric && o.target && o.date);
  scores.push({ id: 'C3', name: crit.C3.name, max: crit.C3.max, method: 'deterministic',
    points: Math.min(crit.C3.max, validObjectives.length * crit.C3.points_per_valid_objective),
    rationale: `${validObjectives.length} of ${objectives.length} objectives have metric + target + date` });
  if (objectives.length - validObjectives.length > 0) flag('OBJECTIVE_NOT_MEASURABLE', 'info', `${objectives.length - validObjectives.length} objective(s) missing metric, target or date`);
  const c4 = (sumOk ? 5 : 0) + (withinCap ? 5 : 0) + (lines.length && !uncategorized.length ? 5 : 0);
  scores.push({ id: 'C4', name: crit.C4.name, max: crit.C4.max, method: 'deterministic', points: c4,
    rationale: `sum matches: ${sumOk}; within cap: ${withinCap}; all lines categorized: ${lines.length > 0 && !uncategorized.length}` });
  const end = val(extraction.timeline_end);
  const inWindow = end && end <= rulebook.dtp_review.implementation_must_end_by;
  const hasOwner = !!val(extraction.responsible_person);
  const tools = (eoi.digitalTools || []).filter((t) => t !== 'None currently').length;
  const c5 = (inWindow ? 4 : 0) + (hasOwner ? 3 : 0) + Math.min(3, tools);
  scores.push({ id: 'C5', name: crit.C5.name, max: crit.C5.max, method: 'deterministic', points: c5,
    rationale: `timeline ends in window: ${!!inWindow}; responsible person: ${hasOwner}; digital tools: ${tools}` });
  const c6 = crit.C6.points_by_export_experience[eoi.exportExperience] || 0;
  scores.push({ id: 'C6', name: crit.C6.name, max: crit.C6.max, method: 'deterministic', points: c6, rationale: `EOI: ${eoi.exportExperience}` });

  const total = scores.reduce((a, s) => a + s.points, 0);
  const borderline = Math.abs(total - S.pass_threshold) <= S.borderline_band;
  if (borderline) flag('BORDERLINE', 'warning', `Preliminary score ${total} is within ±${S.borderline_band} of the ${S.pass_threshold} threshold — mandatory panel review`);

  const blocking = flags.filter((f) => f.severity === 'blocking');
  let recommendation;
  if (blocking.some((f) => f.code === 'MISSING_DOC' || f.code === 'REGISTRATION_UNVERIFIED')) recommendation = 'REQUEST_INFORMATION_FROM_MSME';
  else if (borderline) recommendation = 'BORDERLINE_PANEL_MUST_DECIDE';
  else if (total >= S.pass_threshold && !blocking.length) recommendation = 'RECOMMEND_FOR_PANEL_APPROVAL';
  else recommendation = 'BELOW_THRESHOLD_PANEL_TO_CONFIRM';

  return {
    tier: { ...tier, used: tierKey, grant_cap: grantCap },
    checks, flags,
    score: { total, max: S.max_points, threshold: S.pass_threshold, borderline, breakdown: scores },
    recommendation,
    disclaimer: 'Preliminary result prepared by rules + AI extraction. The evaluation panel decides eligibility and the final score.',
  };
}


