const REPORT_SCHEMA_HINT = {
  report_date: 'field(YYYY-MM-DD)',
  payment_payer: 'field', payment_payee: 'field', payment_amount: 'field(number, BZD)',
  payment_date: 'field(YYYY-MM-DD)', payment_reference: 'field',
  invoice_issuer: 'field', invoice_number: 'field', invoice_date: 'field(YYYY-MM-DD)', invoice_amount: 'field(number, BZD)',
  contract_provider: 'field', contract_value: 'field(number, BZD)', contract_signed: 'field(YYYY-MM-DD)',
  milestones: '[{ objective_id, status(completed|in_progress|not_started), evidence, quote, page }]',
};

function docsToText(documents) {
  return documents.map((d) => `=== DOCUMENT: ${d.type} | ${d.name} ===\n${d.text}`).join('\n\n');
}

function buildExtractionRequest(kind, documents, rulebook, extra = {}) {
  const schema = kind === 'dtp' ? DTP_SCHEMA_HINT : REPORT_SCHEMA_HINT;
  const categories = rulebook.dtp_review.service_categories.join(', ');
  const criteria = rulebook.screening.criteria.filter((c) => c.method !== 'deterministic')
    .map((c) => `${c.id} "${c.name}" (0-${c.max})`).join('; ');
  const system = [
    'You are a document extraction component inside a public grant program workflow (BELTRAIDE DIBED, Belize).',
    'Your ONLY job is to extract values from the documents provided. You do not decide eligibility, scores, matches or approvals.',
    'Rules:',
    '1. Return ONLY valid JSON, no prose, no markdown fences.',
    '2. A "field" is an object: {"value": ..., "quote": "<exact text copied from the document>", "page": <page number from the [Page N] marker>, "confidence": <0..1>}.',
    '3. "quote" must be copied verbatim from the document (max 25 words). If a value is not in the documents, return {"value": null, "quote": null, "page": null, "confidence": 0}. Never guess.',
    `4. Budget and service categories must be one of: ${categories}. Use "uncategorized" if none fits.`,
    kind === 'dtp' ? `5. suggested_scores: suggest points ONLY for ${criteria}, each with a one-sentence rationale and a supporting quote. These are suggestions for a human panel, not decisions.` : '5. milestones: objective_id refers to the DTP objective ids (O1, O2, ...).',
    '6. Amounts are numbers in BZD without separators.',
  ].join('\n');
  const user = [
    `Extract this JSON structure:\n${JSON.stringify(schema, null, 2)}`,
    extra.context ? `Context:\n${extra.context}` : '',
    `Documents:\n${docsToText(documents)}`,
  ].filter(Boolean).join('\n\n');
  return {
    model: (extra.model || rulebook.ai.model),
    max_tokens: rulebook.ai.max_tokens,
    temperature: rulebook.ai.temperature,
    system,
    messages: [{ role: 'user', content: user }],
  };
}

function parseModelJson(apiResponse) {
  const text = (apiResponse && apiResponse.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  const cleaned = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end < 0) throw new Error('Model did not return JSON');
  return JSON.parse(cleaned.slice(start, end + 1));
}

function normalizeSpace(s) {
  return String(s || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();
}

function verifyCitations(extraction, documents, minConfidence = 0.8) {
  // Walks every {value, quote} pair and checks the quote exists in the source documents.
  const corpus = normalizeSpace(documents.map((d) => d.text).join('\n'));
  const issues = [];
  let checked = 0;
  let verified = 0;
  const visit = (node, path) => {
    if (Array.isArray(node)) { node.forEach((n, i) => visit(n, `${path}[${i}]`)); return; }
    if (!node || typeof node !== 'object') return;
    if ('quote' in node && node.quote) {
      checked += 1;
      const q = normalizeSpace(node.quote).replace(/\.\.\.|…/g, '');
      const ok = q.length > 0 && corpus.includes(q.slice(0, Math.min(q.length, 120)));
      if (ok) verified += 1;
      else {
        node.confidence = Math.min(Number(node.confidence ?? 1), 0.3);
        node.citation_verified = false;
        issues.push({ path, quote: node.quote, problem: 'CITATION_NOT_FOUND' });
      }
      if (ok) node.citation_verified = true;
    }
    if ('confidence' in node && 'value' in node && node.value !== null && Number(node.confidence) < minConfidence &&
        !issues.find((i) => i.path === path)) {
      issues.push({ path, value: node.value, problem: 'LOW_CONFIDENCE', confidence: node.confidence });
    }
    for (const [k, v] of Object.entries(node)) if (v && typeof v === 'object') visit(v, path ? `${path}.${k}` : k);
  };
  visit(extraction, '');
  return { checked, verified, issues };
}

function val(field) {
  // Reads the value of a {value, quote, ...} field, tolerating plain values.
  if (field && typeof field === 'object' && 'value' in field) return field.value;
  return field ?? null;
}

function estimateCostUsd(usage, rulebook) {
  if (!usage) return 0;
  const p = rulebook.ai.cost_assumptions_usd_per_million_tokens;
  return ((usage.input_tokens || 0) * p.input + (usage.output_tokens || 0) * p.output) / 1e6;
}


// STEP 3 — Advisor review & DTP versions.
// Structured review checks: each check is resolved by a RULE, suggested by the AI (with citation),
// or left to the ADVISOR's judgment. Versions are hashed; the approved version is locked.
// Depends on: val (extraction.js), sha256 (util.js)

function advisorChecks({ extraction, rulebook, approvedAmount }) {
  const R = rulebook.dtp_review;
  const out = [];
  const add = (id, section, question, method, result, evidence) => out.push({ id, section, question, method, result, evidence });

  const objectives = extraction.objectives || [];
  objectives.forEach((o, i) => {
    const ok = !!(o.metric && o.target && o.date);
    add(`R3.01.${i + 1}`, 'Objectives', `Objective ${o.id || i + 1} has metric + target + date`, 'rule', ok ? 'pass' : 'fail',
      { text: o.text, metric: o.metric, target: o.target, date: o.date, quote: o.quote, page: o.page });
  });
  if (!objectives.length) add('R3.01', 'Objectives', 'At least one objective is defined', 'rule', 'fail', null);

  const lines = extraction.budget_lines || [];
  const bad = lines.filter((l) => !R.service_categories.includes(l.category));
  add('R3.02', 'Budget', 'Every budget line maps to a service category in the catalog', 'rule', bad.length ? 'fail' : 'pass',
    bad.map((l) => ({ description: l.description, category: l.category, quote: l.quote })));

  const total = lines.reduce((a, b) => a + (Number(b.amount) || 0), 0);
  add('R3.03', 'Budget', 'Budget total ≤ approved grant amount', 'rule', approvedAmount !== null && total <= approvedAmount ? 'pass' : 'fail',
    { budget_total: total, approved_amount: approvedAmount });

  const end = val(extraction.timeline_end);
  add('R3.04', 'Timeline', `Implementation ends by ${R.implementation_must_end_by} (program window)`, 'rule',
    end && end <= R.implementation_must_end_by ? 'pass' : 'fail', { timeline_end: end });

  const services = new Set(extraction.services_required || []);
  const solution = String(val(extraction.solution_summary) || '').toLowerCase();
  const mentioned = R.service_categories.filter((c) => solution.includes(c.replace('_', ' ')) || solution.includes(c));
  const unbudgeted = mentioned.filter((c) => !services.has(c));
  add('R3.05', 'Budget vs scope', 'Services described in the solution are budgeted', 'ai_suggestion',
    unbudgeted.length ? 'needs_advisor' : 'pass', { described_not_budgeted: unbudgeted, note: 'Suggestion only — advisor confirms' });

  add('R3.06', 'Viability', 'The business has the people and connectivity to operate the solution', 'advisor', 'needs_advisor',
    { responsible_person: val(extraction.responsible_person) });

  return out;
}

function dtpVersionRecord({ caseId, version, documents, extraction, author, note }) {
  const text = documents.filter((d) => d.type === 'dtp').map((d) => d.text).join('\n');
  return {
    case_id: caseId, version, author, note: note || null,
    hash: sha256(text), created_at: new Date().toISOString(),
    status: 'submitted',
    summary: {
      objectives: (extraction.objectives || []).length,
      budget_total: (extraction.budget_lines || []).reduce((a, b) => a + (Number(b.amount) || 0), 0),
      services: extraction.services_required || [],
    },
  };
}

function diffVersions(prevExtraction, nextExtraction, rulebook) {
  const changes = [];
  const sum = (e) => (e.budget_lines || []).reduce((a, b) => a + (Number(b.amount) || 0), 0);
  const a = sum(prevExtraction);
  const b = sum(nextExtraction);
  if (a !== b) {
    const ratio = a ? Math.abs(b - a) / a : 1;
    changes.push({ section: 'Budget', from: a, to: b, change_ratio: Math.round(ratio * 100) / 100,
      alert: ratio > rulebook.dtp_review.budget_change_alert_ratio ? 'BUDGET_CHANGE_ABOVE_THRESHOLD' : null });
  }
  const objKey = (o) => `${o.id}|${o.metric}|${o.target}|${o.date}`;
  const prevO = new Set((prevExtraction.objectives || []).map(objKey));
  const nextO = (nextExtraction.objectives || []).filter((o) => !prevO.has(objKey(o)));
  if (nextO.length) changes.push({ section: 'Objectives', changed: nextO.map((o) => `${o.id}: ${o.text}`) });
  const sv = (e) => (e.services_required || []).slice().sort().join(',');
  if (sv(prevExtraction) !== sv(nextExtraction)) changes.push({ section: 'Services', from: prevExtraction.services_required, to: nextExtraction.services_required });
  return changes;
}

function lockApprovedVersion(record, advisor) {
  return { ...record, status: 'approved', approved_by: advisor, approved_at: new Date().toISOString(), locked: true,
    lock_note: 'Immutable reference for matchmaking (step 4) and report reviews (steps 8 and 11). Any change requires a new approval.' };
}


