const DTP_SCHEMA_HINT = {
  business_name: 'field', registration_number: 'field', district: 'field',
  employees: 'field(number)', annual_sales: 'field(number, BZD)', capital_investment: 'field(number, BZD)',
  manufacturing_space_m2: 'field(number|null)', amount_requested: 'field(number, BZD)',
  budget_total_declared: 'field(number, BZD)', responsible_person: 'field',
  problem_statement: 'field', solution_summary: 'field',
  timeline_start: 'field(YYYY-MM-DD)', timeline_end: 'field(YYYY-MM-DD)',
  objectives: '[{ text, metric, target, date(YYYY-MM-DD|null), quote, page }]',
  budget_lines: '[{ category, description, amount(number), quote, page }]',
  services_required: '[category]',
  suggested_scores: '{ C1: { points, rationale, quote, page }, C2: { points, rationale, quote, page } }',
};

const REPORT_SCHEMA_HINT = {
  report_date: 'field(YYYY-MM-DD)',
  payment_payer: 'field', payment_payee: 'field', payment_amount: 'field(number, BZD)',
  payment_date: 'field(YYYY-MM-DD)', payment_reference: 'field',
  invoice_issuer: 'field', invoice_number: 'field', invoice_date: 'field(YYYY-MM-DD)', invoice_amount: 'field(number, BZD)',
  contract_provider: 'field', contract_value: 'field(number, BZD)', contract_signed: 'field(YYYY-MM-DD)',
  milestones: '[{ objective_id, status(completed|in_progress|not_started), evidence, quote, page }]',
};

function docsToText(documents) {
  return documents.map((d) => `=== DOCUMENT: ${d.type} | ${d.name} ===\n${d.text}`).join('\n\n');
}

function buildExtractionRequest(kind, documents, rulebook, extra = {}) {
  const schema = kind === 'dtp' ? DTP_SCHEMA_HINT : REPORT_SCHEMA_HINT;
  const categories = rulebook.dtp_review.service_categories.join(', ');
  const criteria = rulebook.screening.criteria.filter((c) => c.method !== 'deterministic')
    .map((c) => `${c.id} "${c.name}" (0-${c.max})`).join('; ');
  const system = [
    'You are a document extraction component inside a public grant program workflow (BELTRAIDE DIBED, Belize).',
    'Your ONLY job is to extract values from the documents provided. You do not decide eligibility, scores, matches or approvals.',
    'Rules:',
    '1. Return ONLY valid JSON, no prose, no markdown fences.',
    '2. A "field" is an object: {"value": ..., "quote": "<exact text copied from the document>", "page": <page number from the [Page N] marker>, "confidence": <0..1>}.',
    '3. "quote" must be copied verbatim from the document (max 25 words). If a value is not in the documents, return {"value": null, "quote": null, "page": null, "confidence": 0}. Never guess.',
    `4. Budget and service categories must be one of: ${categories}. Use "uncategorized" if none fits.`,
    kind === 'dtp' ? `5. suggested_scores: suggest points ONLY for ${criteria}, each with a one-sentence rationale and a supporting quote. These are suggestions for a human panel, not decisions.` : '5. milestones: objective_id refers to the DTP objective ids (O1, O2, ...).',
    '6. Amounts are numbers in BZD without separators.',
  ].join('\n');
  const user = [
    `Extract this JSON structure:\n${JSON.stringify(schema, null, 2)}`,
    extra.context ? `Context:\n${extra.context}` : '',
    `Documents:\n${docsToText(documents)}`,
  ].filter(Boolean).join('\n\n');
  return {
    model: (extra.model || rulebook.ai.model),
    max_tokens: rulebook.ai.max_tokens,
    temperature: rulebook.ai.temperature,
    system,
    messages: [{ role: 'user', content: user }],
  };
}

function parseModelJson(apiResponse) {
  const text = (apiResponse && apiResponse.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  const cleaned = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end < 0) throw new Error('Model did not return JSON');
  return JSON.parse(cleaned.slice(start, end + 1));
}

function normalizeSpace(s) {
  return String(s || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();
}

function verifyCitations(extraction, documents, minConfidence = 0.8) {
  // Walks every {value, quote} pair and checks the quote exists in the source documents.
  const corpus = normalizeSpace(documents.map((d) => d.text).join('\n'));
  const issues = [];
  let checked = 0;
  let verified = 0;
  const visit = (node, path) => {
    if (Array.isArray(node)) { node.forEach((n, i) => visit(n, `${path}[${i}]`)); return; }
    if (!node || typeof node !== 'object') return;
    if ('quote' in node && node.quote) {
      checked += 1;
      const q = normalizeSpace(node.quote).replace(/\.\.\.|…/g, '');
      const ok = q.length > 0 && corpus.includes(q.slice(0, Math.min(q.length, 120)));
      if (ok) verified += 1;
      else {
        node.confidence = Math.min(Number(node.confidence ?? 1), 0.3);
        node.citation_verified = false;
        issues.push({ path, quote: node.quote, problem: 'CITATION_NOT_FOUND' });
      }
      if (ok) node.citation_verified = true;
    }
    if ('confidence' in node && 'value' in node && node.value !== null && Number(node.confidence) < minConfidence &&
        !issues.find((i) => i.path === path)) {
      issues.push({ path, value: node.value, problem: 'LOW_CONFIDENCE', confidence: node.confidence });
    }
    for (const [k, v] of Object.entries(node)) if (v && typeof v === 'object') visit(v, path ? `${path}.${k}` : k);
  };
  visit(extraction, '');
  return { checked, verified, issues };
}

function val(field) {
  // Reads the value of a {value, quote, ...} field, tolerating plain values.
  if (field && typeof field === 'object' && 'value' in field) return field.value;
  return field ?? null;
}

function estimateCostUsd(usage, rulebook) {
  if (!usage) return 0;
  const p = rulebook.ai.cost_assumptions_usd_per_million_tokens;
  return ((usage.input_tokens || 0) * p.input + (usage.output_tokens || 0) * p.output) / 1e6;
}


// STEPS 8 & 11 — Report validators. Each rule returns pass / fail / needs_review with cited evidence.
// The validator never accepts a report and never triggers a payment: staff decide.
// Depends on: val (extraction.js)

function rule(id, name, result, detail, evidence) { return { id, rule: name, result, detail, evidence: evidence || null }; }
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const ev = (f) => (f && f.quote ? { quote: f.quote, page: f.page } : null);

function validateFirstReport({ x, documents, ctx, registry, rulebook }) {
  // ctx: { approved_dsp_name, tranche_amount, agreement_signed, objectives, report_due }
  const R = rulebook.reports;
  const results = [];
  const required = ['progress_report', 'payment_receipt', 'invoice', 'contract'];
  const present = new Set(documents.map((d) => d.type));
  const missing = required.filter((t) => !present.has(t));
  results.push(rule('R8.01', 'All required report documents uploaded', missing.length ? 'fail' : 'pass', { missing }));

  const payee = val(x.payment_payee);
  results.push(rule('R8.02', 'Payee is the DSP approved in step 4', payee && norm(payee) === norm(ctx.approved_dsp_name) ? 'pass' : 'fail',
    { payee, approved_dsp: ctx.approved_dsp_name }, ev(x.payment_payee)));

  const paid = val(x.payment_amount);
  const share = paid !== null && ctx.tranche_amount ? paid / ctx.tranche_amount : null;
  results.push(rule('R8.03', `Amount paid ≥ ${R.min_share_of_tranche_paid * 100}% of the first tranche and ≤ tranche`,
    share === null ? 'fail' : share >= R.min_share_of_tranche_paid && share <= 1 + R.invoice_payment_tolerance ? 'pass' : 'needs_review',
    { paid, tranche: ctx.tranche_amount, share: share === null ? null : Math.round(share * 100) + '%' }, ev(x.payment_amount)));

  const pdate = val(x.payment_date);
  results.push(rule('R8.04', 'Payment made after the grant agreement was signed', pdate && pdate >= ctx.agreement_signed ? 'pass' : 'fail',
    { payment_date: pdate, agreement_signed: ctx.agreement_signed }, ev(x.payment_date)));

  const inv = val(x.invoice_amount);
  const invOk = inv !== null && paid !== null && Math.abs(inv - paid) <= inv * R.invoice_payment_tolerance;
  results.push(rule('R8.05', 'Invoice amount matches the payment', invOk ? 'pass' : 'fail', { invoice: inv, payment: paid }, ev(x.invoice_amount)));

  const provider = val(x.contract_provider);
  results.push(rule('R8.06', 'Contract is with the approved DSP', provider && norm(provider) === norm(ctx.approved_dsp_name) ? 'pass' : 'fail',
    { contract_provider: provider }, ev(x.contract_provider)));

  const invNo = val(x.invoice_number);
  const docHashes = documents.map((d) => d.hash).filter(Boolean);
  const dupInv = invNo && (registry.invoice_numbers || []).some((n) => norm(n.number) === norm(invNo) && n.case_id !== ctx.case_id);
  const dupDoc = docHashes.some((h) => (registry.document_hashes || []).some((r) => r.hash === h && r.case_id !== ctx.case_id));
  results.push(rule('R8.07', 'No document or invoice reused from another case', dupInv || dupDoc ? 'fail' : 'pass',
    { invoice_number: invNo, duplicate_invoice: !!dupInv, duplicate_file: dupDoc }));

  const reportDate = val(x.report_date) || ctx.report_due;
  const due = (ctx.objectives || []).filter((o) => o.date && o.date <= reportDate);
  const ms = x.milestones || [];
  const unevidenced = due.filter((o) => { const m = ms.find((k) => k.objective_id === o.id); return !m || !m.evidence; });
  results.push(rule('R8.08', 'Milestones due by the report date have evidence', unevidenced.length ? 'fail' : 'pass',
    { due: due.map((o) => o.id), without_evidence: unevidenced.map((o) => o.id) }));

  const notStarted = ms.filter((m) => m.status === 'not_started').map((m) => m.objective_id);
  results.push(rule('R8.09', 'Progress consistent with the approved DTP (AI suggestion, staff confirms)',
    notStarted.length ? 'needs_review' : 'pass', { not_started: notStarted }));

  const lowConf = Object.entries(x).filter(([, f]) => f && typeof f === 'object' && 'confidence' in f && f.value !== null && f.confidence < R.min_field_confidence).map(([k]) => k);
  results.push(rule('R8.10', `Extracted data confidence ≥ ${R.min_field_confidence}`, lowConf.length ? 'needs_review' : 'pass', { low_confidence_fields: lowConf }));

  return summarize(results, 'first');
}

function validateFinalReport({ x, ctx, rulebook }) {
  const results = [];
  const ms = x.milestones || [];
  const objectives = ctx.objectives || [];
  const missingEv = objectives.filter((o) => { const m = ms.find((k) => k.objective_id === o.id); return !m || !m.evidence || m.status !== 'completed'; });
  results.push(rule('R11.01', 'Every DTP objective is completed with evidence', missingEv.length ? 'fail' : 'pass', { not_completed: missingEv.map((o) => o.id) }));
  const paidTotal = (ctx.first_payment || 0) + (val(x.payment_amount) || 0);
  const gap = ctx.approved_amount - paidTotal;
  results.push(rule('R11.02', 'Total paid to the DSP is consistent with the total grant', Math.abs(gap) <= ctx.approved_amount * 0.05 ? 'pass' : 'needs_review',
    { first_payment: ctx.first_payment, final_payment: val(x.payment_amount), total_paid: paidTotal, approved_amount: ctx.approved_amount }, ev(x.payment_amount)));
  results.push(rule('R11.03', 'Final payment made to the approved DSP', norm(val(x.payment_payee)) === norm(ctx.approved_dsp_name) ? 'pass' : 'fail',
    { payee: val(x.payment_payee) }, ev(x.payment_payee)));
  results.push(rule('R11.04', 'No open flags from the first report', (ctx.open_flags_from_step8 || 0) === 0 ? 'pass' : 'needs_review', { open: ctx.open_flags_from_step8 || 0 }));
  return summarize(results, 'final');
}

function summarize(results, kind) {
  const fails = results.filter((r) => r.result === 'fail').length;
  const reviews = results.filter((r) => r.result === 'needs_review').length;
  return {
    kind, results,
    counts: { pass: results.length - fails - reviews, fail: fails, needs_review: reviews },
    preliminary: fails ? 'DISCREPANCIES_FOUND' : reviews ? 'NEEDS_REVIEW' : 'ALL_CHECKS_PASSED',
    disclaimer: kind === 'first'
      ? 'Staff accept or reject the report. Acceptance is the condition for the second disbursement; this system never executes payments.'
      : 'Staff accept the final report and close the case.',
  };
}


// HTML pages shown to each human at each gate (rendered inside n8n Form pages).
// Only tags allowed by the n8n form sanitizer are used (h3, p, b, table, ul, li, code, i).

function esc(s) {
  return String(s === null || s === undefined ? '—' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const icon = (r) => ({ pass: '✅', fail: '❌', needs_review: '⚠️', needs_advisor: '🟠', info: 'ℹ️' }[r] || '•');
const sevIcon = (s) => ({ blocking: '⛔', warning: '⚠️', info: 'ℹ️' }[s] || '•');

function caseHeader(c) {
  return `<p><b>Case ${esc(c.case_id)}</b> · ${esc(c.msme.business_name)} · ${esc(c.msme.sector)} · ${esc(c.msme.district || 'district not found')}</p>`;
}

function slaLine(sla) {
  if (!sla) return '';
  return `<p><i>Step SLA: ${esc(sla.sla_days)} days · started ${esc(sla.started_at.slice(0, 10))} · due by <b>${esc(sla.due_at ? sla.due_at.slice(0, 10) : '—')}</b></i></p>`;
}

function flagsTable(flags) {
  if (!flags || !flags.length) return '<p>No flags.</p>';
  return `<table><thead><tr><th></th><th>Flag</th><th>What the reviewer should look at</th></tr></thead><tbody>${
    flags.map((f) => `<tr><td>${sevIcon(f.severity)}</td><td><code>${esc(f.code)}</code></td><td>${esc(f.message)}</td></tr>`).join('')
  }</tbody></table>`;
}

function checksTable(checks) {
  return `<table><thead><tr><th></th><th>Rule</th><th>Check</th><th>Detail</th></tr></thead><tbody>${
    checks.map((k) => `<tr><td>${icon(k.result)}</td><td><code>${esc(k.id)}</code></td><td>${esc(k.rule || k.question)}</td><td>${esc(typeof k.detail === 'object' ? JSON.stringify(k.detail) : k.detail ?? (k.evidence ? JSON.stringify(k.evidence) : ''))}</td></tr>`).join('')
  }</tbody></table>`;
}

function intakePage(c) {
  const i = c.steps.intake;
  return [
    caseHeader(c),
    `<h3>Pre-screening result (automatic rules on your Expression of Interest)</h3>`,
    checksTable(i.checks),
    flagsTable(i.flags),
    `<p>Declared category: <b>${esc(i.declared_tier)}</b> · Indicative grant cap: <b>BZD ${esc(i.indicative_grant_cap)}</b></p>`,
    `<h3>Next: formal application</h3><p>Choose a demo application package (synthetic Belizean MSME) or paste your own DTP text.</p>`,
  ].join('');
}

function extractionTable(x) {
  const rows = [
    ['Business name', x.business_name], ['Registration number', x.registration_number], ['Employees', x.employees],
    ['Annual sales (BZD)', x.annual_sales], ['Capital investment (BZD)', x.capital_investment],
    ['Amount requested (BZD)', x.amount_requested], ['Declared budget total', x.budget_total_declared],
    ['Timeline end', x.timeline_end], ['Responsible person', x.responsible_person],
  ];
  return `<table><thead><tr><th>Field</th><th>Value</th><th>Source (quote · page)</th><th>Conf.</th></tr></thead><tbody>${
    rows.map(([k, f]) => {
      const v = f && typeof f === 'object' ? f : { value: f };
      const ok = v.citation_verified === false ? ' ❌ quote not found' : '';
      return `<tr><td>${esc(k)}</td><td><b>${esc(v.value)}</b></td><td><i>“${esc(v.quote)}”</i> · p.${esc(v.page)}${ok}</td><td>${esc(v.confidence)}</td></tr>`;
    }).join('')
  }</tbody></table>`;
}

function panelPage(c) {
  const s = c.steps.screening;
  const x = c.extraction.dtp_v1;
  return [
    caseHeader(c), slaLine(c.sla.screening),
    `<h3>Preliminary result: ${esc(s.recommendation)}</h3>`,
    `<p><b>Preliminary score ${esc(s.score.total)} / ${esc(s.score.max)}</b> (threshold ${esc(s.score.threshold)}${s.score.borderline ? ', BORDERLINE' : ''}) · Tier: <b>${esc(s.tier.used)}</b> · Grant cap: BZD ${esc(s.tier.grant_cap)}</p>`,
    `<p><i>Extractor: ${esc(c.ai_runs[c.ai_runs.length - 1].mode)} · citations verified ${esc(c.ai_runs[c.ai_runs.length - 1].citations_verified)}/${esc(c.ai_runs[c.ai_runs.length - 1].citations_checked)}</i></p>`,
    `<table><thead><tr><th>Criterion</th><th>Points</th><th>Method</th><th>Rationale / evidence</th></tr></thead><tbody>${
      s.score.breakdown.map((b) => `<tr><td>${esc(b.id)} ${esc(b.name)}</td><td><b>${esc(b.points)}</b> / ${esc(b.max)}</td><td>${esc(b.method)}${b.needs_human_confirmation ? ' — confirm' : ''}</td><td>${esc(b.rationale)}${b.quote ? ` <i>“${esc(String(b.quote).slice(0, 160))}”</i> p.${esc(b.page)}` : ''}</td></tr>`).join('')
    }</tbody></table>`,
    `<h3>Flags</h3>`, flagsTable(s.flags),
    `<h3>Rules applied</h3>`, checksTable(s.checks),
    `<h3>Extracted evidence (AI, cited)</h3>`, extractionTable(x),
    `<p><i>${esc(s.disclaimer)}</i></p>`,
  ].join('');
}

function advisorPage(c) {
  const v = c.dtp_versions[c.dtp_versions.length - 1];
  const diff = c.steps.advisor.diff || [];
  return [
    caseHeader(c), slaLine(c.sla.advisor_review),
    `<h3>DTP version v${esc(v.version)} · hash <code>${esc(v.hash.slice(0, 16))}…</code></h3>`,
    diff.length ? `<p><b>Changes vs previous version:</b></p><ul>${diff.map((d) => `<li>${esc(d.section)}: ${esc(JSON.stringify(d))}</li>`).join('')}</ul>` : '',
    `<h3>Structured review checks</h3><p>✅ rule passed · ❌ rule failed · 🟠 needs your judgment (AI suggestions are only suggestions)</p>`,
    `<table><thead><tr><th></th><th>Check</th><th>Section</th><th>Question</th><th>Resolved by</th><th>Evidence</th></tr></thead><tbody>${
      c.steps.advisor.checks.map((k) => `<tr><td>${icon(k.result)}</td><td><code>${esc(k.id)}</code></td><td>${esc(k.section)}</td><td>${esc(k.question)}</td><td>${esc(k.method)}</td><td>${esc(JSON.stringify(k.evidence))}</td></tr>`).join('')
    }</tbody></table>`,
    c.steps.advisor.comments && c.steps.advisor.comments.length ? `<h3>Previous comments</h3><ul>${c.steps.advisor.comments.map((m) => `<li>v${esc(m.version)} · ${esc(m.by)}: ${esc(m.text)}</li>`).join('')}</ul>` : '',
  ].join('');
}

function revisionPage(c) {
  const last = c.steps.advisor.comments[c.steps.advisor.comments.length - 1];
  return [caseHeader(c), `<h3>Your advisor requested changes</h3>`, `<p>${esc(last ? last.text : '')}</p>`,
    `<p>Upload a revised DTP. The previous version is preserved; the system will compare both versions for the advisor.</p>`].join('');
}

function preferencesPage(c, roster) {
  const a = c.approved_dtp;
  return [caseHeader(c), `<h3>Approved DTP (locked v${esc(a.version)}, hash <code>${esc(a.hash.slice(0, 16))}…</code>)</h3>`,
    `<p>Services required: <b>${esc(a.services_required.join(', '))}</b> · Approved amount: <b>BZD ${esc(a.approved_amount)}</b></p>`,
    `<h3>Digital Service Providers in the roster</h3><table><thead><tr><th>DSP</th><th>Categories</th><th>Location</th></tr></thead><tbody>${
      roster.map((d) => `<tr><td>${esc(d.name)}</td><td>${esc(d.categories.join(', '))}</td><td>${esc(d.district)}</td></tr>`).join('')
    }</tbody></table>`,
    `<p>Confirm your interest and (optionally) tell us which providers you prefer. Program staff approve the final match.</p>`].join('');
}

function matchPage(c) {
  const m = c.steps.matching;
  return [caseHeader(c), slaLine(c.sla.matchmaking),
    `<h3>Explainable shortlist (weights ${esc(Object.entries(m.weights).map(([k, w]) => `${k} ${w * 100}%`).join(' · '))})</h3>`,
    `<p><i>${esc(m.weights_note)}</i></p>`,
    `<table><thead><tr><th>#</th><th>DSP</th><th>Score</th><th>Quote</th><th>Weeks</th><th>Covers</th><th>Breakdown</th></tr></thead><tbody>${
      m.shortlist.map((s) => `<tr><td>${s.rank}</td><td><b>${esc(s.dsp_name)}</b></td><td><b>${esc(s.total_score)}</b></td><td>BZD ${esc(s.quote_total)}</td><td>${esc(s.quote_weeks)}</td><td>${esc(s.covered.join(', '))}</td><td>${esc(s.explanation.join(' | '))}</td></tr>`).join('')
    }</tbody></table>`,
    m.excluded.length ? `<h3>Excluded by hard filters</h3><ul>${m.excluded.map((e) => `<li>${esc(e.dsp_name)}: ${esc(e.failed_filters.join(', '))}</li>`).join('')}</ul>` : '',
    `<h3>Flags</h3>`, flagsTable(m.flags),
    `<p><i>${esc(m.disclaimer)} If you do not select #1, a reason is mandatory.</i></p>`].join('');
}

function reportUploadPage(c, kind) {
  return [caseHeader(c),
    kind === 'first'
      ? `<h3>First progress report</h3><p>Approved DSP: <b>${esc(c.match.dsp_name)}</b> · First tranche received: <b>BZD ${esc(c.disbursements.first.amount)}</b> on ${esc(c.disbursements.first.date)}</p><p>Upload: progress report, proof of payment to the DSP, DSP invoice, MSME–DSP contract.</p>`
      : `<h3>Final report</h3><p>Upload the final report with evidence for every objective and the proof of the final payment to <b>${esc(c.match.dsp_name)}</b>.</p>`,
  ].join('');
}

function reportReviewPage(c, kind) {
  const v = kind === 'first' ? c.steps.report_1 : c.steps.final_report;
  const sla = kind === 'first' ? c.sla.report_1_review : c.sla.final_review;
  return [caseHeader(c), slaLine(sla),
    `<h3>${kind === 'first' ? 'First report' : 'Final report'} validation: ${esc(v.preliminary)}</h3>`,
    `<p>✅ ${v.counts.pass} pass · ❌ ${v.counts.fail} fail · ⚠️ ${v.counts.needs_review} need review</p>`,
    `<table><thead><tr><th></th><th>Rule</th><th>Check</th><th>Detail</th><th>Evidence</th></tr></thead><tbody>${
      v.results.map((r) => `<tr><td>${icon(r.result)}</td><td><code>${esc(r.id)}</code></td><td>${esc(r.rule)}</td><td>${esc(JSON.stringify(r.detail))}</td><td>${r.evidence ? `<i>“${esc(r.evidence.quote)}”</i> p.${esc(r.evidence.page)}` : ''}</td></tr>`).join('')
    }</tbody></table>`,
    `<p><i>${esc(v.disclaimer)}</i></p>`].join('');
}

function caseRecordPage(c) {
  const cost = c.ai_runs.reduce((a, r) => a + (r.cost_usd || 0), 0);
